249	          <BackToTop />
250	        </div>
251	      )}
252	    </>
253	  );
254	
255	  const children = (
256	    <MentionResolutionProvider contents={contents}>
257	      <div ref={layoutMeasureRef} className="w-full">
258	        <div className={cn("flex flex-col justify-start w-full mx-auto", useGrid ? "max-w-none" : "max-w-2xl")}>
259	          {/* During initial load, show the spinner only after the delay; render nothing before then to avoid a flash. */}
260	          {isLoading ? (
261	            showLoader ? (
262	              <Loader />
263	            ) : null
264	          ) : useGrid ? (
265	            <>
266	              <ColumnGrid
267	                items={sortedMemoList}
268	                getKey={getMemoKey}
269	                renderItem={(memo) => props.renderer(memo, { compact: effectiveCompact })}
270	                estimateHeight={estimateMemoCardHeight}
271	                leading={gridLeading}
272	                priorityKey={priorityKey}
273	                maxColumns={maxColumns}
274	                maxColumnWidth={MAX_COLUMN_WIDTH}
275	              />
276	              {footer}
277	            </>
278	          ) : (
279	            <>
280	              {memoEditor}
281	              <MemoFilters className="mb-2" />
282	              {sortedMemoList.map((memo) => props.renderer(memo, { compact: effectiveCompact }))}
283	              {emptyPlaceholder}
284	              {footer}
285	            </>
286	          )}
287	        </div>
288	      </div>
289	    </MentionResolutionProvider>
290	  );
291	
292	  return children;
293	};
294	
295	const BackToTop = () => {
296	  const t = useTranslate();
297	  const [isVisible, setIsVisible] = useState(false);
298	
299	  useEffect(() => {
300	    const handleScroll = () => {
301	      const shouldShow = window.scrollY > 400;
302	      setIsVisible(shouldShow);
303	    };
304	
305	    window.addEventListener("scroll", handleScroll);
306	    return () => window.removeEventListener("scroll", handleScroll);
307	  }, []);
308	
309	  const scrollToTop = () => {
310	    window.scrollTo({
311	      top: 0,
312	      behavior: "smooth",
313	    });
314	  };
315	
316	  // Don't render if not visible
317	  if (!isVisible) {
318	    return null;
319	  }
320	
321	  return (
322	    <Button variant="ghost" onClick={scrollToTop}>
323	      {t("router.back-to-top")}
324	      <ArrowUpIcon className="ml-1 w-4 h-auto" />
325	    </Button>
326	  );
327	};
328	
329	export default PagedMemoList;
